package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.time.Duration;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Projection;
import org.eclipse.rdf4j.query.algebra.ProjectionElem;
import org.eclipse.rdf4j.query.algebra.ProjectionElemList;
import org.eclipse.rdf4j.query.algebra.QueryRoot;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.Var;
import org.junit.jupiter.api.Test;

/**
 * A pipeline plan cache waiter parked on a flight whose owner fails must compute its own plan instead of inheriting the
 * owner's failure as a {@link java.util.concurrent.CompletionException}.
 */
class LmdbPipelinePlanCacheFailedFlightTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void waiterComputesOwnPlanWhenOwnerFails() throws Exception {
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(8, 1, 1024 * 1024L);
		LmdbPipelinePlanCache.Context context = context(17L);
		AtomicInteger computations = new AtomicInteger();
		CountDownLatch ownerEntered = new CountDownLatch(1);
		CountDownLatch releaseOwner = new CountDownLatch(1);
		ExecutorService executor = Executors.newFixedThreadPool(2);
		try {
			QueryRoot ownerSource = query("_anon_1", "urn:left");
			Future<LmdbPipelinePlanCache.Result> owner = executor.submit(() -> cache.getOrCompute(
					ownerSource, context, context::revision, () -> {
						computations.incrementAndGet();
						ownerEntered.countDown();
						await(releaseOwner);
						throw new IllegalArgumentException("owner planning failed");
					}));
			assertTrue(ownerEntered.await(Duration.ofSeconds(5).toMillis(), TimeUnit.MILLISECONDS));

			QueryRoot waiterSource = query("_anon_2", "urn:left");
			Future<LmdbPipelinePlanCache.Result> waiter = executor.submit(() -> cache.getOrCompute(
					waiterSource, context, context::revision, () -> planned(waiterSource, computations)));
			long deadline = System.nanoTime() + Duration.ofSeconds(5).toNanos();
			while (cache.waits() == 0L && System.nanoTime() < deadline) {
				Thread.onSpinWait();
			}
			assertEquals(1L, cache.waits(), "the second request must have parked on the owner's flight");
			releaseOwner.countDown();

			ExecutionException ownerFailure = assertThrows(ExecutionException.class,
					() -> owner.get(10, TimeUnit.SECONDS));
			assertInstanceOf(IllegalArgumentException.class, ownerFailure.getCause(),
					"the owner keeps its own failure");
			LmdbPipelinePlanCache.Result replanned = waiter.get(10, TimeUnit.SECONDS);
			assertNotNull(replanned.plan());
			assertFalse(replanned.cacheHit(), "a plan computed after a failed flight is not a cache hit");
			assertEquals(2, computations.get(), "owner (failed) + waiter (own computation)");
		} finally {
			releaseOwner.countDown();
			executor.shutdownNow();
		}
	}

	private static QueryRoot query(String anonymousName, String predicate) {
		StatementPattern pattern = new StatementPattern(
				Var.of(anonymousName, true), Var.of("predicate", VF.createIRI(predicate)), Var.of("object"));
		Projection projection = new Projection(pattern, new ProjectionElemList(new ProjectionElem("object")));
		return new QueryRoot(projection);
	}

	private static TupleExpr planned(TupleExpr plan, AtomicInteger computations) {
		computations.incrementAndGet();
		plan.setStringMetricPlanned(LmdbCascadesOptimizer.APPLIED_METRIC, "true");
		return plan;
	}

	private static void await(CountDownLatch latch) {
		try {
			latch.await();
		} catch (InterruptedException interrupted) {
			Thread.currentThread().interrupt();
			throw new AssertionError("interrupted while coordinating cache flight", interrupted);
		}
	}

	private static LmdbPipelinePlanCache.Context context(long dataRevision) {
		LmdbEstimatorRuntime.PlanningRevisions planning = new LmdbEstimatorRuntime.PlanningRevisions(
				dataRevision, 2L, 3L, 4L);
		return new LmdbPipelinePlanCache.Context(
				new LmdbPipelinePlanCache.Revision(planning, true), false, 0L,
				LmdbPipelinePlanCache.DatasetIdentity.of(null), LmdbPipelinePlanCache.BindingIdentity.of(null), "",
				false, false, false, "STANDARD", false);
	}
}
